function shortQuestion(line,n,pairs,label){const [answer,desc]=rotate(pairs,n);return q({prompt:`${label}. ${desc}. Назовите биологический термин.`,answer:[answer],difficulty:diff(n),explanation:`По ключевым признакам определяется: ${answer}.`,solutionSteps:['Выделите диагностические признаки','Сопоставьте их с определением','Запишите термин без лишних слов']});}
function matchingQuestion(line,n,pairs,label){const start=(n-1)%pairs.length,selected=[0,1,2,3].map(k=>pairs[(start+k*3)%pairs.length]);const right=selected.map(x=>x[0]);const shift=n%4;const shown=right.map((_,i)=>right[(i+shift)%4]);const left=selected.map(x=>x[1]);const answer=selected.map((x,i)=>`${i}-${shown.indexOf(x[0])}`);return q({prompt:`${label}. Установите соответствие между характеристиками и объектами.`,type:'matching',questionType:'matching',answer,difficulty:diff(n),content:{left,right:shown,answerEncoding:'pairs'},explanation:'Каждую характеристику нужно сопоставить с единственным наиболее подходящим объектом.',solutionSteps:['Рассмотрите каждую характеристику отдельно','Найдите диагностический признак','Проверьте получившуюся последовательность']});}
function multipleQuestion(line,n,groups,label){const [target,correct,wrong]=rotate(groups,n);const all=[...correct,...wrong];const shift=n%all.length;const options=all.map((_,i)=>all[(i+shift)%all.length]);const answer=correct.map(x=>String(options.indexOf(x)));return q({prompt:`${label}. Выберите три верных утверждения о ${target}.`,type:'multiple',questionType:'multiple_answer',answer,difficulty:diff(n),options:options.map((label,i)=>({value:String(i),label})),explanation:`Верные утверждения следуют из ключевых признаков ${target}.`,solutionSteps:['Проверяйте каждое утверждение независимо','Отделите обязательные признаки от случайных','Выберите только три верных пункта']});}
function sequenceQuestion(line,n,list,label){const [name,steps]=rotate(list,n);const shift=n%steps.length;const shown=steps.map((_,i)=>steps[(i+shift)%steps.length]);const options=shown.map((label,i)=>({value:`s${steps.indexOf(label)}`,label}));const answer=steps.map((_,i)=>`s${i}`);return q({prompt:`${label}: ${name}. Установите правильную последовательность этапов.`,type:'sequence',questionType:'sequence',answer,difficulty:diff(n),options,explanation:`Процесс «${name}» идёт в причинно и/или временно определённой последовательности.`,solutionSteps:['Найдите начальный этап','Восстановите причинные связи','Проверьте конечный этап']});}
function line3(n){const mode=(n-1)%3;if(mode===0){const total=120+12*n,a=30+2*n,g=(total-2*a)/2;return q({prompt:`В двуцепочечном фрагменте ДНК ${total} нуклеотидов, из них адениновых ${a}. Сколько в этом фрагменте гуаниновых нуклеотидов?`,answer:[String(g)],difficulty:diff(n),explanation:`В двуцепочечной ДНК A=T, G=C. После вычитания A и T оставшиеся нуклеотиды поровну приходятся на G и C: ${g}.`,solutionSteps:['Найдите число T','Вычтите A и T из общего числа','Разделите остаток пополам']});}if(mode===1){const aa=40+n,nt=(aa+1)*3;return q({prompt:`Кодирующая часть мРНК содержит ${nt} нуклеотидов, включая один стоп-кодон. Сколько аминокислот будет в полипептиде?`,answer:[String(aa)],difficulty:diff(n),explanation:`Число кодонов равно ${nt}/3=${aa+1}; стоп-кодон аминокислоту не кодирует, поэтому остаётся ${aa}.`,solutionSteps:['Разделите число нуклеотидов на 3','Учтите стоп-кодон','Запишите число аминокислот']});}const prod=10000+1000*n,level=2+(n%2),ans=prod/(10**level);return q({prompt:`Биомасса продуцентов экосистемы равна ${prod} кг. Используя правило примерно 10%, оцените биомассу консументов ${level}-го порядка. Ответ дайте в килограммах.`,answer:[String(ans)],difficulty:diff(n),explanation:`При каждом переходе сохраняется около 10% энергии/биомассы: ${prod} → ${prod/10}${level===2?` → ${ans}`:` → ${prod/100} → ${ans}`}.`,solutionSteps:['Определите число трофических переходов','Каждый раз делите на 10','Проверьте порядок величины']});}
function line4(n){const mode=(n-1)%4;if(mode===0){const total=80+16*n,ans=total/4;return q({prompt:`Скрестили двух гетерозигот Aa × Aa. Получено ${total} потомков. Сколько в среднем ожидается особей с рецессивным фенотипом aa?`,answer:[String(ans)],difficulty:diff(n),explanation:`При Aa × Aa вероятность aa равна 1/4, поэтому ${total}/4=${ans}.`,solutionSteps:['Запишите расщепление 1:2:1','Найдите долю aa','Умножьте на число потомков']});}if(mode===1){const total=160+16*n,ans=total*3/16;return q({prompt:`При независимом наследовании генов скрестили AaBb × AaBb и получили ${total} потомков. Сколько в среднем ожидается особей с фенотипом A–bb?`,answer:[String(ans)],difficulty:diff(n),explanation:`P(A–)=3/4, P(bb)=1/4; совместная вероятность 3/16. ${total}×3/16=${ans}.`,solutionSteps:['Найдите вероятность доминантного фенотипа A–','Найдите вероятность bb','Перемножьте независимые вероятности']});}if(mode===2){const total=100+20*n,ans=total/2;return q({prompt:`При анализирующем скрещивании Aa × aa получено ${total} потомков. Сколько в среднем будет иметь доминантный фенотип?`,answer:[String(ans)],difficulty:diff(n),explanation:`При Aa × aa ожидается расщепление 1:1, поэтому половина потомков имеет доминантный фенотип: ${ans}.`,solutionSteps:['Определите типы гамет','Получите соотношение 1:1','Возьмите половину от общего числа']});}const total=320+32*n,ans=total/16;return q({prompt:`Скрестили AaBb × AaBb. Сколько из ${total} потомков в среднем будут двойными рецессивами aabb при независимом наследовании?`,answer:[String(ans)],difficulty:diff(n),explanation:`P(aa)=1/4 и P(bb)=1/4, поэтому P(aabb)=1/16. ${total}/16=${ans}.`,solutionSteps:['Рассчитайте вероятность aa','Рассчитайте вероятность bb','Перемножьте вероятности']});}
function extendedQuestion(line,n){const item=rotate(extended[line],n);if(line===22){const [theme,ind,dep,controls]=item;const criteria=[`Независимая переменная: ${ind}.`,`Зависимая переменная: ${dep}.`,`Контролируемые условия: ${controls}.`,'Нужна контрольная группа или исходный уровень, отличающийся только исследуемым фактором.'];return q({prompt:`Спланируйте эксперимент: ${theme}. Укажите гипотезу, независимую и зависимую переменные, не менее двух контролируемых условий и принцип контрольной группы.`,type:'text',questionType:'extended_answer',answer:[criteria.join(' ')],difficulty:diff(n),content:{manualReview:true,criteria},explanation:criteria.join(' '),solutionSteps:criteria,maxScore:3});}const [prompt,criteria]=item;return q({prompt,type:'text',questionType:'extended_answer',answer:[criteria.join(' ')],difficulty:diff(n),content:{manualReview:true,criteria},explanation:criteria.join(' '),solutionSteps:criteria,maxScore:line===26?4:3});}
function build(line,n){
 if(line===1)return shortQuestion(line,n,science,'Задание на биологические науки и методы');
 if(line===2)return matchingQuestion(line,n,expScenarios.map(x=>[x[0],`В опыте изменяют ${x[0]}`]),'Методология эксперимента');
 if(line===3)return line3(n); if(line===4)return line4(n);
 if(line===5)return shortQuestion(line,n,organelles,'На учебной схеме структура описана следующими признаками');
 if(line===6)return matchingQuestion(line,n,cellPairs,'Клетка и органоиды');
 if([7,11,15,17,18,21].includes(line))return multipleQuestion(line,n,multiGroups[line],registry.lines.find(x=>x.line===line).title);
 if([8,12,16].includes(line))return sequenceQuestion(line,n,processes[line],registry.lines.find(x=>x.line===line).title);
 if(line===9)return shortQuestion(line,n,diversityId,'Определите объект многообразия по описанию');
 if(line===10)return matchingQuestion(line,n,diversityPairs,'Многообразие организмов');
 if(line===13)return shortQuestion(line,n,humanId,'Определите структуру организма человека по описанию');
 if(line===14)return matchingQuestion(line,n,humanPairs,'Органы и функции человека');
 if(line===19)return matchingQuestion(line,n,evoEcoPairs,'Эволюция и экология');
 if(line===20)return matchingQuestion(line,n,tablePairs,'Заполните биологическую таблицу: сопоставьте процесс и характеристику');
 if(line>=22&&line<=28)return extendedQuestion(line,n);
 throw new Error(`No builder for biology line ${line}`);
}

async function ensureBiologyLineBank(db,{minimum=15}={}){
 const subject=await db.row("SELECT id FROM subjects WHERE slug='biology'");
 if(!subject)return {inserted:0,lines:[]};
 let inserted=0;const report=[];
 for(const lineInfo of registry.lines){
   const line=Number(lineInfo.line);let count=Number((await db.row('SELECT COUNT(*) n FROM questions WHERE subject_id=? AND exam_line=? AND active=1',subject.id,line))?.n||0);
   const lesson=await db.row(`SELECT l.id,l.topic_id FROM lessons l JOIN topics t ON t.id=l.topic_id WHERE t.subject_id=? AND l.slug IN (${lineInfo.lessonRefs.map(()=>'?').join(',')}) ORDER BY CASE l.slug ${lineInfo.lessonRefs.map((_,i)=>`WHEN ? THEN ${i}`).join(' ')} ELSE 999 END LIMIT 1`,subject.id,...lineInfo.lessonRefs,...lineInfo.lessonRefs);
   if(!lesson){report.push({line,count,inserted:0,warning:'lesson-not-found'});continue;}
   let added=0;
   for(let n=1;count<minimum&&n<=60;n++){
     const externalKey=`biology-bank-v4-line${line}-${n}`;
     if(await db.row('SELECT id FROM questions WHERE external_key=?',externalKey))continue;
     const item=build(line,n),maxScore=item.maxScore||lineInfo.maxScore||1;
     const result=await db.run(`INSERT INTO questions(subject_id,topic_id,lesson_id,external_key,type,question_type,prompt,instruction,explanation,difficulty,answer_json,answer_data_json,explanation_json,content_json,media_json,source,source_type,exam_line,points,estimated_seconds,active,published,exam_year,solution_steps_json,max_score,content_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,TRUE,TRUE,?,?,?,?,?)`,subject.id,lesson.topic_id,lesson.id,externalKey,item.type,item.questionType,item.prompt,item.instruction,item.explanation,item.difficulty,JSON.stringify(item.answer),JSON.stringify({correct:item.answer,acceptedVariants:item.acceptedVariants||[],content:item.content||{}}),JSON.stringify({short:item.explanation,fullSolution:item.explanation,scoringPoints:item.content?.criteria||[]}),JSON.stringify(item.content||{}),'{}','Оригинальный банк ОСНОВА','original',line,maxScore,line>=22?360:120,2027,JSON.stringify(item.solutionSteps||[]),maxScore,'review');
     const questionId=Number(result.lastInsertRowid);
     for(const [i,opt] of (item.options||[]).entries())await db.run('INSERT INTO question_options(question_id,value,label,position) VALUES(?,?,?,?)',questionId,String(opt.value),String(opt.label),i);
     count++;added++;inserted++;
   }
   report.push({line,count,inserted:added});
 }
 return {inserted,lines:report};
}
module.exports={ensureBiologyLineBank,build};
